// Cargar scripts de variaciones/galería en una página estática con shortcode [product_page]
add_action('wp_enqueue_scripts', function () {
  if (is_page(123)) { // <--- CAMBIA 123 por el ID de tu página
    // JS de Woo necesarios para variaciones e imagen de producto
    wp_enqueue_script('wc-add-to-cart-variation');
    wp_enqueue_script('wc-single-product');

    // A veces la galería usa flexslider: lo forzamos si existe
    if (wp_script_is('flexslider', 'registered')) {
      wp_enqueue_script('flexslider');
    }
  }
}, 20);

// Re-inicializar los formularios de variación y la galería en esa página
add_action('wp_footer', function () {
