/* Reemplazar el mensaje "Tu cuenta fue creada correctamente..." en todo WooCommerce */
add_filter('gettext', function ($translated_text, $text, $domain) {
    if ($domain === 'woocommerce') {
        $searches = [
            'Tu cuenta fue creada correctamente y se envió una contraseña a tu dirección de correo electrónico.',
            'Your account was created successfully and a password was sent to your email address.'
        ];

        foreach ($searches as $s) {
            if (stripos($translated_text, $s) !== false) {
                return 'Hemos recibido tu solicitud de registro. La estamos revisando y en breve nos pondremos en contacto contigo. Tras la aprobación recibirás un email para establecer tu contraseña.';
            }
        }
    }
    return $translated_text;
}, 999, 3);

